// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(0));
        address originalOwner = c.owner();
        vm.prank(nonOwner);
        try c.setOwner(address(0xdead)) {} catch {}
        assertTrue(c.owner() == originalOwner);
    }
}
